def peak_of(self, env):
    bounds = env[0]
    mx = None
    u = 0
    for p in range(self.P):
        vp = self.vTph[p]
        for i in range(self.N):
            b = bounds[u]
            if b is None:
                return None
            c = b + vp[i]
            if mx is None or c > mx:
                mx = c
            u += 1
    return mx

def peak_of_matrix(self, B):
