def peaks_and_choice(self):
    """Exact peak per guard setting plus the smallest safe setting.

    Also returns the envelope of the chosen setting when it was computed
    here, so that the caller can avoid recomputing it."""
    guards = self.guards
    reconf = self.reconfig * NS_AS
    peaks = []
    cache = {}
    chosen = None
    chosen_env = None
    for g in guards:
        c = self.guard_edge_count(g)
        if c in cache:
            pk = cache[c]
        else:
            env = self.envelope(g)
            pk = self.peak_of(env)
            cache[c] = pk
            if chosen is None and pk is not None and g * NS_AS >= pk + reconf:
                chosen = g
                chosen_env = env
                env = None
        peaks.append(pk)
        if chosen is None and pk is not None and g * NS_AS >= pk + reconf:
            chosen = g
    return peaks, chosen, chosen_env

def plan(self):
    calib = self.calib
    peaks, chosen, env = self.peaks_and_choice()
    base = {'status': 'ok',
            'profile': calib.artifact(),
            'period_rounds': self.P,
            'peaks_as': peaks,
            'guard_ns': chosen}
